{"id":"CQ-009","category":"code_quality","criterion":"error_handling","severity":"LOW","score":4,"file":"head/.claude/scripts/red-test-check.sh","line":216,"reasoning_trace":"worktree add --detach does not initialise submodules.","finding":"Submodule-mode consumers get dangling .claude symlinks in both worktrees.","remediation":"submodule update --init --recursive when .gitmodules exists.","confidence":"medium","references":[]}
{"id":"CQ-010","category":"code_quality","criterion":"documentation","severity":"LOW","score":4,"file":"head/.claude/scripts/validate-artifact.sh","line":867,"reasoning_trace":"No CHANGELOG hunk in the diff; CHANGELOG absent from this workspace.","finding":"CHANGELOG entry for the new gates unverified.","remediation":"Confirm the [Unreleased] entry.","confidence":"low","references":[]}
{"id":"CQ-011","category":"code_quality","criterion":"documentation","severity":"LOW","score":4,"file":"head/.claude/loa/GLOSSARY.md","line":68,"reasoning_trace":"--report on the live kernel: 0 defined, 5 alias, 11 allowlisted.","finding":"_Aliases_ carries non-synonyms; no definition is exercised by the drift gate.","remediation":"_States_/_Related_ annotation or backtick defined terms in the kernel.","confidence":"medium","references":[]}
